from a different location.

:param loaders: The sequence of loaders to try in order.
:param path_transform: Optional callable that receives a template
    path and returns the transformed path to use for resolution.
    The transformation is applied at the top level before delegating
    to the child loaders.

.. versionchanged:: 3.1
    Added the ``path_transform`` parameter.
"""

def __init__(
    self,
    loaders: t.Sequence[BaseLoader],
    path_transform: t.Optional[t.Callable[[str], str]] = None,
) -> None:
    self.loaders = loaders
    self.path_transform = path_transform

def get_source(
    self, environment: "Environment", template: str
) -> t.Tuple[str, t.Optional[str], t.Optional[t.Callable[[], bool]]]:
    original = template
    template = self._transform_path(template)
    for loader in self.loaders:
        try:
            return loader.get_source(environment, template)
        except TemplateNotFound:
            pass
    raise TemplateNotFound(original)

